insert into public.study_methods (topic, position, heading, kind, items) values
('korean', 1, '과목 특징', 'list', '["2025년부터 암기형에서 이해·추론형으로 바뀌었어요. 2025년 지방직은 20문항 중 확인추론·응용추론·논리비판이 15문항이었고 문학은 나오지 않았어요.","==지식을 쌓는 과목이 아니라 정해진 시간 안에 읽고 판단하는 기술 과목==으로 다루는 편이 출제 기조와 맞아요.","암기형 문법 규정 대신 공문서 고쳐쓰기로 어휘·문장 구성 능력을 물어요.","2027년부터 25문항이 돼요. 영역별 배분은 아직 발표되지 않았으니 시간 배분과 풀이 순서를 미리 정해 두는 게 좋아요."]'::jsonb),
('korean', 2, '단계별 공부법', 'pairs', '[{"label":"기본","text":"인사혁신처 예시문제로 유형부터 확인해요. 국어학·논리학 개념은 필요한 만큼만 익히고, 추론·논리 문제를 매일 조금씩 풀어요"},{"label":"기출","text":"2025년 이후 신기조 기출과 예시문제를 반복해요. 2024년 이전 기출의 문법·한자·문학 문항은 효용이 낮은 편이에요"},{"label":"실전","text":"신기조 대비 모의고사로 문제량을 채우고, 시간을 재고 풀어요. 합격자 사례에서는 격일 모의고사에서 시험 한두 달 전 매일 모의고사로 늘렸어요"},{"label":"마무리","text":"틀린 유형과 실수 노트 위주로 봐요. 새 문법 범위는 늘리지 않아요"}]'::jsonb),
('korean', 3, '고민별 처방', 'pairs', '[{"label":"추론 문제가 감으로 풀림","text":"지문 밖 배경지식은 빼고, 지문 안 근거 문장에 표시한 뒤 선지와 맞춰 봐요"},{"label":"강화·약화 문제를 자주 틀림","text":"**지문의 주장을 먼저 한 줄로 요약**하고, 선지가 그 주장을 지지하는지 반박하는지 판단해요"},{"label":"명제논리가 헷갈림","text":"기호로 바꾸고 대우·삼단논법 같은 기본 규칙으로 풀어요. 감으로 풀지 않아요"},{"label":"독해 시간이 부족함","text":"주장과 대립·동의 지점을 표시하며 요약하듯 읽고, 지문당 목표 시간을 정해요"},{"label":"실수로 틀림","text":"부정형 발문에 표시하고 선지를 끝까지 읽어요. 어려운 문항은 표시하고 넘겨요"},{"label":"문법·한자 암기에 시간을 많이 씀","text":"우선순위를 낮춰요. 확인·응용추론 → 논리비판 → 의사소통·공문서 → 지문형 국어학 순서가 안전해요"}]'::jsonb),
('english', 1, '과목 특징', 'list', '["2025·2026년 국가직은 두 해 모두 어휘 3, 문법 3, 생활영어 2, 독해 12문항이었어요. ==독해가 점수를 가르고, 시간 압박이 가장 큰 과목==이에요.","어휘는 밑줄 동의어 고르기에서 문장 문맥에 맞는 단어 고르기로 바뀌었어요. 다만 독해 지문이 길어 독해용 어휘량은 줄지 않았다고 보는 편이 안전해요.","문법은 빈칸형 1문항, 밑줄 중 틀린 것 고르기 2문항이었어요. 병치처럼 문장 구조를 분석해야 하는 문항이 나와요.","독해 오답은 빈칸·삽입·순서·삭제 네 유형에 몰려요. 공지문·이메일·안내문 같은 실용문도 나와요.","합격생 설문에서 영어는 부담 과목 2위였지만, 30% 정도는 3개월 안에 점수가 올랐다고 답했어요."]'::jsonb),
('english', 2, '단계별 공부법', 'pairs', '[{"label":"기본","text":"단어를 매일 정해진 양만큼 외우고, 문법 개념을 실제 문장에 적용해 봐요. 기초가 부족하면 기초 어휘 → 기초 문법 → 구문 독해 순서로 문장을 해석할 수 있는 상태부터 만들어요"},{"label":"기출","text":"2025·2026년 기출과 예시문제를 시간 재고 풀어요. 2024년 이전 기출은 어휘·문법 기본기 점검용으로만 써요"},{"label":"실전","text":"하프 모의고사를 15분 제한으로 풀고, 25문항 기준으로 시간을 줄이는 연습을 해요"},{"label":"마무리","text":"누적 단어장과 오답 위주로 봐요. 단어 암기는 시험 직전까지 끊지 않아요"}]'::jsonb),
('english', 3, '고민별 처방', 'pairs', '[{"label":"단어가 금방 잊힘","text":"**하루 50개 안팎을 매일** 외우고, 이동 시간에 다시 봐요. 하루 양을 늘리기보다 끊기지 않게 해요"},{"label":"빈칸 문제를 자주 틀림","text":"빈칸 위치와 그 문장의 구조를 먼저 확인하고, 근거 문장에 표시해요"},{"label":"삽입·순서 문제를 자주 틀림","text":"연결어·접속사·대명사를 단서로 앞뒤 문장을 이어 봐요"},{"label":"무관한 문장 찾기를 틀림","text":"문장 사이 흐름이 아니라 글의 주제에서 벗어났는지로 판단해요"},{"label":"독해 시간이 부족함","text":"실전과 같은 시간 안에 풀어요. 실용문은 제목과 날짜·장소·대상 같은 정보 항목을 먼저 훑는 방법이 도움이 되는 편이에요"},{"label":"점수가 오르지 않음","text":"오답을 어휘 부족·구조 파악 실패·시간 부족으로 나누고, 가장 많은 원인부터 고쳐요. 매일 모든 과목은 계획대로 하고 영어에 추가 시간을 써요"},{"label":"생활영어에서 실수함","text":"빈출 표현을 익히되, 대화 흐름상 들어갈 말을 고르는 연습에 무게를 둬요"}]'::jsonb),
('english', 4, '하루 공부 예시', 'list', '["단어 50개 안팎(이동 시간 반복 포함)","하프 모의고사 1회, 15분 제한","틀린 문제와 모르는 단어 정리"]'::jsonb),
('public_health', 1, '과목 특징', 'list', '["같은 주제가 해마다 되풀이돼요. 식품 보존법, 국민건강증진종합계획, 먹는물 수질 기준, 오존이 여러 해 반복해 나왔어요. ==반복 출제 주제는 무실점==이 목표예요.","**역학은 매년 출제**돼요. 연구 설계(단면·코호트·환자-대조군), 발생률·유병률, 민감도, 감염재생산수 같은 개념이 나왔어요.","검역법, 진료기록 보존기간, 암검진, 금연구역처럼 법령 세부 조항까지 문항이 돼요.","개정 사항이 직접 문항이 돼요. 2026년 3월 제6차 국민건강증진종합계획(2026~2030)이 발표됐고, 니파바이러스감염증은 제1급 감염병으로 지정됐다고 보도됐어요.","건강보험·법규·보건사업 기획처럼 보건행정과 겹치는 문항이 가장 큰 묶음으로 보여요. 두 과목을 함께 공부하면 효율적이에요."]'::jsonb),
('public_health', 2, '단계별 공부법', 'pairs', '[{"label":"기본","text":"강의나 기본서로 전체 단원을 한 번 돌리고, 같은 주에 그 단원 기출을 함께 풀어요"},{"label":"기출","text":"기출을 반복하되, 점수가 멈추면 기본서로 돌아가 정의·수치를 다시 봐요. 기출을 볼 때는 \"내가 무엇을 놓치고 있나\"를 기준으로 삼아요"},{"label":"실전","text":"모의고사로 구멍 난 단원을 찾고, 그 단원만 기본서로 다시 회독해요"},{"label":"마무리","text":"시험 2~3개월 전부터 법령 개정 이력, 감염병 분류표, 국민건강증진종합계획 원문을 교재와 대조해요. 마지막 2주는 전공 최종 정리에 써요"}]'::jsonb),
('public_health', 3, '고민별 처방', 'pairs', '[{"label":"기출은 맞는데 시험에서 틀림","text":"기출만 훑으면 \"안다는 착각\"이 생겨요. ==기본서로 돌아가 정의·수치를 손으로 쓰며 정밀하게 외워요=="},{"label":"외울 게 너무 많음","text":"반복 출제 주제부터 확실히 해요. 감염병 급별 목록, 매개체·병원체, 식중독 원인균, 환경 기준 수치, 법정 기간은 표로 만들어요"},{"label":"외워도 금방 잊힘","text":"표를 덮고 백지에 다시 써 보며 확인해요(백지 복기). 간격을 두고 반복해요"},{"label":"감염병이 헷갈림","text":"급별 종수보다 특정 질환의 급수, 신고 시기, 최근 새로 들어간 질환이 함정이 되기 쉬워요"},{"label":"역학·통계 계산이 어려움","text":"치명률, 민감도·특이도, 상대위험도·교차비 같은 공식을 분자·분모까지 한 장에 정리하고 기출 계산 문항을 반복해요. 계산 문제는 해마다 0~2문항 정도로 보여요"},{"label":"보건행정과 겹치는 부분이 헷갈림","text":"사회보장·건강보험, 보건법규, 보건사업 기획·평가 모형은 한쪽 교재에 모아 두 과목 회독 때마다 함께 봐요"},{"label":"기본서와 기출 중 무엇을 반복할지 모르겠음","text":"기출 → 기본서 왕복이 기본이에요. 기출 밖에서도 나온다고 보고 기본서를 3~4회독한 합격자 사례도 있으니 내게 맞는 쪽을 골라요"}]'::jsonb),
('health_admin', 1, '과목 특징', 'list', '["반복 출제 주제가 뚜렷해요. 예산(준예산, 예산 원칙, 추경), 인사평정 오류, 도나베디안 질 평가, BPRS, 의료기관 인증이 여러 해 나왔어요.","행정이론(조직·인사·재무·기획과 정책)이 해마다 7~11문항 정도로 가장 큰 덩어리로 보여요. 법규·보건조직은 3문항 안팎으로 일정한 편이에요.","==변별은 법령 세부 요건에서 나와요.== 요양병원 입원 대상, 신의료기술평가 대상, 전문병원 지정 요건처럼 시행규칙 수준까지 출제됐어요.","건강보험·의료보장 세부(본인부담상한제, DRG, 재가급여 본인부담, 현금급여)와 학자·모형 이름을 연결하는 문항이 해마다 있어요.","공중보건과 겹치는 범위가 커서 두 과목을 함께 공부하면 효율적이에요."]'::jsonb),
('health_admin', 2, '단계별 공부법', 'pairs', '[{"label":"기본","text":"이론 강의나 기본서로 단원 흐름을 잡아요. 행정학 기본서를 따로 볼 필요는 낮은 편이고, 보건행정 기본서의 해당 단원과 기출로 충분해 보여요"},{"label":"기출","text":"기출을 풀며 이론 노트를 복습하고, 구멍이 드러난 단원은 기본서를 정독한 뒤 다시 기출로 돌아가요"},{"label":"실전","text":"모의고사를 실제 OMR로 치러요. 합격자 사례에서 가장 도움이 됐다고 꼽은 방법이에요"},{"label":"마무리","text":"반복해서 틀리는 내용만 모은 노트를 외워요. 본인부담률처럼 해마다 바뀌는 수치는 시험 직전에 법령과 고시로 확인해요"}]'::jsonb),
('health_admin', 3, '고민별 처방', 'pairs', '[{"label":"이론이 다 비슷해 보임","text":"==비교표로 정리해요.== NHI와 NHS, 지불제도별 장단점, 계급제와 직위분류제, 엽관주의와 실적주의, 예산 원칙과 종류, 평정 오류 유형이 좋은 주제예요"},{"label":"학자·모형 이름이 안 외워짐","text":"학자 이름과 모형을 한 줄씩 짝지어 카드로 만들고, 덮고 떠올리며 확인해요"},{"label":"제도가 잘 안 외워짐","text":"건강보험·의료급여·장기요양을 보험자·가입자·급여·재원 같은 틀로 먼저 그림을 그리고, 그 위에 수치를 얹어요"},{"label":"법규 문항을 자주 틀림","text":"**법규는 따로 공부해요.** 의료법과 지역보건법은 조문을 직접 확인해요"},{"label":"공중보건과 겹치는 부분이 헷갈림","text":"겹치는 단원은 한쪽 교재에 모아 두 과목 회독 때마다 함께 보고, 두 과목 기출을 번갈아 풀어요"},{"label":"지엽 문항에 시간을 많이 씀","text":"반복 주제를 먼저 모두 확보하고, 연금·노인복지·산업보건 같은 주변 법제의 지엽 문항은 뒤로 미뤄요"},{"label":"비전공이라 예산·인사·정책이 낯섦","text":"전공 배경에 따라 약한 곳이 달라요. 낯선 단원에 추가 시간을 쓰되, 매일 모든 과목은 계획대로 해요"}]'::jsonb),
('mental', 1, '점수가 떨어졌을 때', 'list', '["==한 회차 점수는 실력이 아니라 오차예요.== 최근 3~4회 평균으로 추세를 봐요.","방향은 하나예요. 틀린 문제를 개념 부족·실수·시간 부족으로 나눠 원인을 찾아요.","점수는 움직여요. 합격자 사례에서도 첫 모의고사 전공 35점이 두 달 뒤 80점대로 올랐어요.","이번 주는 가장 많은 원인 하나만 골라 다음 주 분량에 반영해요. 하나씩 고치면 돼요."]'::jsonb),
('mental', 2, '공부가 손에 안 잡힐 때', 'list', '["안 되는 날은 있어요. 억지로 붙잡은 시간보다 정한 분량을 끝내는 게 중요해요.","오늘 할 일을 가장 작은 단위로 줄여요. 하기 싫은 과목의 한 단원부터 10분만 시작해 봐요.","6개월 만에 합격한 사례에서도 안 되는 날은 반나절 쉬고, 다음 날 분량을 채웠어요.","그래도 안 되면 오늘은 끊고 쉬어요. 못 한 분량은 다음 날로 나눠 두면 돼요."]'::jsonb),
('mental', 3, '불안하고 비교될 때', 'list', '["다른 사람의 진도와 점수는 내 시험 결과를 바꾸지 못해요. 비교가 늘면 SNS와 수험 커뮤니티를 보는 시간부터 줄여요.","불안한 날은 어려운 과목 대신 자신 있는 과목을 정리하며 안정을 찾는 방법도 있어요.","반복해서 읽으면 아는 느낌이 들지만, 실제 기억은 덮고 떠올린 쪽이 더 오래 남아요. 불안할수록 문제로 확인해요.","==2주 이상 무기력이나 수면 문제가 이어지면 혼자 버티지 말고 주변과 전문 상담에 도움을 구해요.=="]'::jsonb),
('mental', 4, '몸과 리듬', 'list', '["시험 전날 하루의 잠보다 수험 기간 내내 규칙적으로 자는 것이 성적과 더 관련이 있었어요.","취침·기상 시각을 평일과 주말 모두 고정해요. 잠을 줄여 공부 시간을 만들지 않아요.","주 1일은 쉬어요. 휴일 없이 달리다 시험 직전에 번아웃을 겪은 합격자 사례가 있고, 초반 과속은 후반 슬럼프로 이어지기 쉬워요.","운동은 성적을 올리는 수단보다 기분과 체력을 지키는 수단으로 생각하고 꾸준히 해요."]'::jsonb),
('mental', 5, '시험 직전', 'list', '["시험 직전 긴장은 실수로 이어지기 쉬워요. 시험 직전 10분 동안 걱정을 글로 적으면 압박 속 정확도가 올랐다는 연구가 있어요.","마지막 2~3주는 주말 모의고사를 실제 시험 시각에 치르고, 걱정 적기를 그 전에 미리 연습해 루틴으로 만들어요.","전날에는 시험장·교통·준비물을 확인해 불확실한 것을 없애요. 전날 잠을 설쳐도 너무 걱정하지 않아도 돼요.","지금까지 쌓은 분량이 실력이에요. 해 온 대로 풀고 오면 돼요."]'::jsonb),
('time', 1, '학습 단계', 'pairs', '[{"label":"기본","text":"시험 6개월 이상 전. 기본서·강의로 전체 구조를 이해하고 1회독해요. 강의와 같은 주에 그 단원 기출을 함께 풀어요"},{"label":"기출","text":"시험 6~3개월 전. 기출을 반복하고 자주 나오는 개념을 정리하며 회독을 늘려요. 요약서(단권화)를 이때 정해요"},{"label":"실전","text":"시험 3~1개월 전. 25문항 동형 모의고사를 주 1회에서 주 2~3회로 늘리고, 110분 통세트로 시간 관리와 오답 정리를 해요"},{"label":"마무리","text":"시험 1개월 이내. 오답과 요약서만 반복하고 새 교재는 늘리지 않아요"}]'::jsonb),
('time', 2, '공통 원칙', 'list', '["시기는 기준일 뿐이에요. 진도가 늦으면 단계를 당기지 말고 남은 기간에 맞춰 회독 범위를 줄여요.","**회독**: 처음부터 완벽하게 외우려 하지 말고 여러 번 빠르게 돌려요. 회독할수록 속도가 붙어요.","**기출 우선**: 무엇이 자주 나오는지 기출로 확인하고, 그 범위를 먼저 확실히 해요.","**오답 관리**: 틀린 문제는 이유(몰라서·헷갈려서·실수)를 나눠 기록하고 다시 풀어요.","**매일 조금씩 모든 과목**: 한 과목에 몰리면 다른 과목 감각이 떨어져요. 약한 과목은 매일 계획을 지키면서 추가 시간을 써요."]'::jsonb),
('time', 3, '수험 기간 설계', 'list', '["합격 사례들은 기간이 짧아도 기본 강의 → 기출·요약서 반복 → 동형 모의고사 주 2~3회 순서를 지켰어요.","시간이 부족하면 일부 과목은 이론을 건너뛰고 기출 강의로 시작한 합격자 사례도 있어요. 시험 한 달 전부터 오답과 헷갈리는 내용만 모은 요약 노트를 만들어요.","암기 과목(공중보건·보건행정)은 기출 반복이 핵심이고, 국어·영어는 새 문제를 계속 접해야 해요.","초반에는 점수가 느리게 오르는 국어·영어 비중을 조금 높이고, 후반으로 갈수록 시험의 절반인 전공 비중을 늘리는 편이 안전해요.","2027년부터 한국사는 한국사능력검정시험 3급 이상으로 대체돼요. 아직 없다면 시험 일정과 별도로 미리 따 둬요."]'::jsonb),
('time', 4, '하루·주간 운영', 'list', '["==시간을 채우기보다 그날 정한 분량을 끝내는 데 집중해요.== 못 채운 분량은 다음 날로 나눠요.","주 1일은 쉬어요. 합격자 사례에서는 시험 한 달 전부터만 휴일 없이 공부했어요.","하루 공부를 가장 하기 싫은 과목·단원부터 시작하는 방법도 있어요.","==회독은 다시 읽기가 아니라 덮고 떠올리기와 기출 풀이로 해요.== 연습 시험과 간격 두고 반복하기가 가장 효과적인 공부법으로 평가됐고, 다시 읽기·밑줄·요약은 효과가 낮았어요.","복습 간격은 시험이 가까울수록 좁혀요. 지금은 같은 단원을 1~3주 간격으로, 시험 1~2개월 전에는 며칠 간격으로, 마지막 주에는 1~2일 간격으로 보는 편이 좋아요."]'::jsonb),
('time', 5, '직장 병행', 'list', '["평일 4~6시간, 주말 8시간 이상으로 합격한 직장인 사례가 있어요. 출근 전 단어, 이동 중 강의, 퇴근 후 이론처럼 시간대를 고정했어요.","공부 시간이 전업보다 적으니 강의 수를 줄이고 기출에 일찍 들어가는 편이 좋아요.","평일은 짧은 블록, 주말은 110분 모의고사 같은 긴 블록으로 나눠요. 일정이 자주 바뀌면 하루보다 주 단위 분량 목표가 덜 무너져요.","잠을 줄여 공부 시간을 만들지 않아요."]'::jsonb),
('time', 6, '시험 당일 110분', 'list', '["110분은 보도 기준이에요. 과목별 제한 시간이 없고 마킹까지 110분 안에 끝내야 해서, 문항당 평균 약 66초예요.","암기 과목에 시간을 적게 쓰고 지문이 긴 국어·영어에 충분히 나눠요. 예를 들어 전공 두 과목 각 18~20분, 국어·영어 각 30~32분, 마킹·검토 8~10분이 한 가지 안이에요.","모의고사로 2~3가지 풀이 순서를 시험해 보고 시험 2개월 전쯤 하나로 정해요.","어려운 문항은 표시하고 넘기고, 마지막 5~10분은 검토에 써요. 모의고사는 110분 타이머로 실전처럼 치러요."]'::jsonb);
